editDirectoryAgent=function(id){
const existing=personalAgents.find(x=>x.id===id),d=document.createElement('dialog');d.className='market-dialog custom-agent-editor';
const names=['创建转库单','创建杂项单','维护物料货位限制关系','维护物料子库限制关系','查询库存现有量及可用量','查询转库单','查询杂项单','查询物料','统一搜索','使用指南',...customSkills.map(s=>s.name)];
d.innerHTML='<header><div><h2>'+(existing?'编辑智能体':'自定义智能体')+'</h2><p>设置智能体的说明、执行指令与可用能力。</p></div><button type="button" aria-label="关闭智能体配置">×</button></header><form><h3>基本信息</h3><label>智能体名称 *<input name="name" placeholder="例如：库存核查智能体" maxlength="40" required value="'+safeText(existing?.name||'')+'"></label><label>说明 *<textarea name="desc" required maxlength="600" placeholder="说明能完成什么，以及何时使用…">'+safeText(existing?.desc||'')+'</textarea></label><h3>提示词与工具</h3><label>执行指令 *<textarea name="instructions" required placeholder="描述目标、处理步骤、约束和预期输出…">'+safeText(existing?.instructions||'')+'</textarea></label><label>技能</label><div class="agent-skill-checkboxes" role="group" aria-label="技能">'+[...new Set(names)].map((name,i)=>'<label><input type="checkbox" name="skills" value="'+safeText(name)+'" '+((existing?.skillNames||existing?.skills?.split(' · ')||[]).includes(name)?'checked':'')+'><span>'+safeText(name)+'</span></label>').join('')+'</div><label>工具<select name="tools" aria-label="工具"><option value=""></option><option>ERPQuery</option><option>ERPQuery · ERPWrite（需确认）</option></select></label><footer><button type="button" data-cancel>取消</button><button class="primary">保存智能体</button></footer></form>';document.body.append(d);d.querySelector('header button').onclick=d.querySelector('[data-cancel]').onclick=()=>d.close();d.onclose=()=>d.remove();const f=d.querySelector('form');f.tools.value=existing?.tools||'';f.onsubmit=e=>{e.preventDefault();const values=new FormData(f),skills=values.getAll('skills'),entry={id:existing?.id||'custom-agent-'+Date.now(),name:values.get('name').trim(),desc:values.get('desc').trim(),instructions:values.get('instructions').trim(),skillNames:skills,skills:skills.join(' · '),tools:values.get('tools'),type:warehouseMarket?'purchase':'analysis',tag:'个人配置'};if(existing){Object.assign(existing,entry);Object.assign(agentCatalog.find(x=>x.id===entry.id),entry)}else{personalAgents.push(entry);agentCatalog.push(entry)}localStorage.setItem('erp-personal-agents',JSON.stringify(personalAgents));d.close();switchMarketTab('agent')};d.showModal()};
